const entries = [
  { id:'birads', term:'BI-RADS', clinical:'Breast Imaging Reporting and Data System', aliases:['bi rads','birads','category','assessment'], summary:'A standard way radiologists describe mammogram findings and their assessment.', explanation:'BI-RADS is a reporting system created by the American College of Radiology. It gives imaging findings a category so that reports can be described consistently. A category is not, by itself, a diagnosis and does not explain what any result means for one person.', questions:['What does this category mean in the context of my report?','Is there anything in my history or prior images that affects how you view this result?'], source:'American College of Radiology — BI-RADS Atlas', url:'https://www.acr.org/Clinical-Resources/Reporting-and-Data-Systems/Bi-Rads', reviewed:'2026-10-15' },
  { id:'birads-0', term:'BI-RADS 0', clinical:'Incomplete — additional imaging evaluation and/or prior mammograms may be needed', aliases:['0','birads 0','bi-rads 0','incomplete'], summary:'The imaging review is not complete yet; more information may be needed.', explanation:'This category means the radiologist needs more information before completing the assessment. That can include extra views or comparison with earlier images. It does not tell you whether you do or do not have cancer.', questions:['What information or imaging is needed to complete the assessment?','Can you explain the timeline for getting the additional information?'], source:'American Cancer Society — Mammogram report terminology', url:'https://www.cancer.org/cancer/risk-prevention/understanding-cancer-risk/breast-cancer-risk-and-prevention/mammogram-reports.html', reviewed:'2026-10-15' },
  { id:'birads-1', term:'BI-RADS 1', clinical:'Negative', aliases:['1','birads 1','bi-rads 1','negative'], summary:'No concerning finding is described in the imaging assessment.', explanation:'In BI-RADS terminology, “negative” means no suspicious finding is described on the imaging exam. It is an imaging assessment, not an all-purpose statement about a person’s health or future risk.', questions:['How does this result fit with my personal screening plan?'], source:'American Cancer Society — Mammogram report terminology', url:'https://www.cancer.org/cancer/risk-prevention/understanding-cancer-risk/breast-cancer-risk-and-prevention/mammogram-reports.html', reviewed:'2026-10-15' },
  { id:'birads-2', term:'BI-RADS 2', clinical:'Benign finding', aliases:['2','birads 2','bi-rads 2','benign'], summary:'A finding is described as noncancerous in the imaging assessment.', explanation:'“Benign” is the word used for a finding that is not cancer. The report may name the type of finding. Your clinician can help place this information alongside your history and any symptoms.', questions:['What benign finding is described in my report?','Does this change anything I should discuss with my clinician?'], source:'American Cancer Society — Mammogram report terminology', url:'https://www.cancer.org/cancer/risk-prevention/understanding-cancer-risk/breast-cancer-risk-and-prevention/mammogram-reports.html', reviewed:'2026-10-15' },
  { id:'birads-3', term:'BI-RADS 3', clinical:'Probably benign finding', aliases:['3','birads 3','bi-rads 3','probably benign'], summary:'The radiologist describes a finding as probably benign, using a standard category.', explanation:'This category is used for a finding the radiologist assesses as probably benign. It does not replace a conversation about the particular report, health history, or the appropriate next step for an individual.', questions:['What characteristics led to this assessment?','What follow-up, if any, are you recommending for my situation?'], source:'American Cancer Society — Mammogram report terminology', url:'https://www.cancer.org/cancer/risk-prevention/understanding-cancer-risk/breast-cancer-risk-and-prevention/mammogram-reports.html', reviewed:'2026-10-15' },
  { id:'density', term:'Breast density', clinical:'Breast tissue composition on a mammogram', aliases:['dense breasts','dense breast tissue','density','heterogeneously dense','extremely dense'], summary:'A description of how breast tissue appears on a mammogram—not how breasts look or feel.', explanation:'Breast density describes the mix of fibrous and glandular tissue compared with fatty tissue as it appears on a mammogram. Dense tissue can make some cancers harder to see on a mammogram. It is common, and it is not a diagnosis. Recommendations about supplemental screening can differ; evidence and guidance do not point to one option that is right for everyone.', questions:['What density category is in my report?','How does my density relate to my own history and risk factors?','Can we discuss the possible benefits and harms of any additional imaging for me?'], source:'National Cancer Institute — Dense Breasts', url:'https://www.cancer.gov/types/breast/screening/dense-breasts', reviewed:'2026-10-15' },
  { id:'calcifications', term:'Calcifications', clinical:'Tiny calcium deposits seen on mammography', aliases:['calcium','microcalcifications','macrocalcifications'], summary:'Small calcium deposits that can appear in breast tissue on a mammogram.', explanation:'Calcifications are small calcium deposits that can be seen on a mammogram. They are common. Their appearance and pattern help a radiologist describe them, but this glossary cannot interpret what a particular report means.', questions:['What type or pattern of calcifications does my report describe?','Can you explain what that description means in my situation?'], source:'American Cancer Society — Mammogram report terminology', url:'https://www.cancer.org/cancer/risk-prevention/understanding-cancer-risk/breast-cancer-risk-and-prevention/mammogram-reports.html', reviewed:'2026-10-15' },
  { id:'mass', term:'Mass', clinical:'A three-dimensional area seen on imaging', aliases:['lump','lesion','nodule'], summary:'A term radiologists may use for an area with a defined shape on imaging.', explanation:'In breast imaging, a mass is an area seen in two different views that has a shape and borders that can be described. It is an imaging term. A report’s other details and a clinician’s assessment are needed to understand a specific finding.', questions:['What features of the mass are described in my report?','What questions should I ask about this finding?'], source:'American Cancer Society — Mammogram report terminology', url:'https://www.cancer.org/cancer/risk-prevention/understanding-cancer-risk/breast-cancer-risk-and-prevention/mammogram-reports.html', reviewed:'2026-10-15' }
];
const $ = (selector) => document.querySelector(selector);
let bookmarks = []; let storageAvailable = true;
try { bookmarks = JSON.parse(localStorage.getItem('mammogram-bookmarks') || '[]'); } catch { storageAvailable = false; }
const search = $('#search'), resultList = $('#resultsList'), topicGrid = $('#topicGrid'), resultMeta = $('#resultMeta');
function persist() { try { localStorage.setItem('mammogram-bookmarks', JSON.stringify(bookmarks)); } catch { storageAvailable = false; } }
function isSaved(id) { return bookmarks.some(b => b.entry_id === id); }
function renderCard(entry) { const tpl = $('#entryTemplate').content.cloneNode(true); const card = tpl.querySelector('.entry-card'); card.dataset.id=entry.id; const open=tpl.querySelector('.entry-open'); open.textContent=entry.term; open.addEventListener('click',()=>openEntry(entry.id)); tpl.querySelector('.entry-summary').textContent=entry.summary; const b=tpl.querySelector('.bookmark-button'); b.textContent=isSaved(entry.id)?'★':'☆'; b.setAttribute('aria-label',`${isSaved(entry.id)?'Remove':'Save'} ${entry.term}`); b.setAttribute('aria-pressed',isSaved(entry.id)); b.addEventListener('click',()=>toggleBookmark(entry.id)); return tpl; }
function runSearch() { const query=search.value.trim().toLowerCase(); resultList.innerHTML=''; $('#clearSearch').hidden=!query; $('#searchAgain').hidden=!query; topicGrid.querySelectorAll('[data-search]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.search.toLowerCase()===query))); const found=entries.filter(e=>[e.term,e.clinical,...e.aliases,e.summary].join(' ').toLowerCase().includes(query)); resultMeta.textContent=query ? `Active filter: “${search.value.trim()}” · ${found.length} ${found.length===1?'entry':'entries'}` : `All available terms · ${found.length} entries`; if(!found.length) { resultList.innerHTML='<div class="empty-state"><h3>No term found yet</h3><p>Try a shorter term, “BI-RADS,” “density,” or a different spelling. This search stays on your device; please don’t include report text or personal information.</p></div>'; return; } found.forEach(e=>resultList.append(renderCard(e))); }
function openEntry(id) { const e=entries.find(item=>item.id===id); if(!e) return; const offline=!navigator.onLine; $('#entryContent').innerHTML=`<div class="dialog-body"><h2 id="dialogTitle">${e.term}</h2><p class="clinical-name">${e.clinical}</p><p>${e.explanation}</p><h3>What to ask your clinician</h3><ul class="question-list">${e.questions.map(q=>`<li>${q}</li>`).join('')}</ul><div class="source-block">${offline?'<span class="offline-tag">External link needs connection</span>':''}Source: <a href="${e.url}" target="_blank" rel="noopener">${e.source} ↗</a></div></div>`; $('#entryDialog').showModal(); }
let feedbackTimer;
function toggleBookmark(id) { const e=entries.find(x=>x.id===id); if(!e) return; const removed=isSaved(id); if(removed) bookmarks=bookmarks.filter(b=>b.entry_id!==id); else if(storageAvailable) bookmarks.push({entry_id:id,saved_at:new Date().toISOString()}); persist(); renderBookmarks(); runSearch(); const activeList=location.hash==='#bookmarks' ? $('#bookmarksList') : resultList; const replacement=activeList.querySelector(`[data-id="${id}"] .bookmark-button`); (replacement || (location.hash==='#bookmarks' ? $('#saved-title') : $('#clearSearch'))).focus(); $('#saveFeedback').textContent=storageAvailable ? `${e.term} ${removed ? 'removed from saved terms' : 'saved on this device'}.` : 'Bookmarks could not be saved in this browser.'; clearTimeout(feedbackTimer); feedbackTimer=setTimeout(()=>{$('#saveFeedback').textContent='';},4000); }
function renderBookmarks() { const saved=entries.filter(e=>isSaved(e.id)); const list=$('#bookmarksList'); list.innerHTML=''; document.querySelectorAll('.saved-count').forEach(count=>{count.textContent=saved.length;count.setAttribute('aria-label',`${saved.length} saved ${saved.length===1?'term':'terms'}`);}); $('#clearBookmarks').hidden=!saved.length; if(!storageAvailable) { list.innerHTML='<div class="saved-message"><strong>Bookmarks aren’t available in this browser.</strong><br />You can still read and search the glossary. This can happen when browser storage is unavailable or was cleared.</div>'; return; } if(!saved.length) { list.innerHTML='<div class="saved-message"><strong>Nothing saved yet.</strong><br />Use the star on a glossary entry to keep it here on this device.</div>'; return; } saved.forEach(e=>list.append(renderCard(e))); }
let updateReady=false;
function updateConnection() { const status=$('#connectionStatus'); const messages=[]; if(!navigator.onLine) messages.push('You’re offline. Glossary content and saved terms are available; external source links need a connection.'); if(updateReady) messages.push('A content update is ready. Refresh or restart the app to load the latest library.'); status.hidden=messages.length===0; status.textContent=messages.join(' '); }
$('#searchButton').addEventListener('click',()=>{runSearch();location.hash='#browse';}); search.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runSearch();location.hash='#browse';}}); document.querySelector('nav a[href="#browse"]').addEventListener('click',runSearch); $('#clearSearch').addEventListener('click',()=>{search.value='';runSearch();topicGrid.querySelector('[data-search=""]').focus();}); $('#searchAgain').addEventListener('click',()=>setTimeout(()=>search.focus(),0)); document.querySelectorAll('[data-home-search]').forEach(button=>button.addEventListener('click',()=>{location.hash='#home';setTimeout(()=>search.focus(),0);})); document.querySelectorAll('[data-search]').forEach(b=>b.addEventListener('click',()=>{search.value=b.dataset.search;runSearch();location.hash='#browse';})); $('#clearBookmarks').addEventListener('click',()=>{if(confirm('Clear all saved terms from this device?')){bookmarks=[];persist();renderBookmarks();runSearch();}}); $('#closeDialog').addEventListener('click',()=>$('#entryDialog').close()); $('#entryDialog').addEventListener('click',(e)=>{if(e.target===$('#entryDialog')) $('#entryDialog').close();}); window.addEventListener('online',updateConnection); window.addEventListener('offline',updateConnection); updateConnection(); renderBookmarks(); runSearch();
if('serviceWorker' in navigator) navigator.serviceWorker.register('./sw.js').then(reg=>{ if(reg.waiting) showUpdate(); reg.addEventListener('updatefound',()=>{const worker=reg.installing; worker?.addEventListener('statechange',()=>{if(worker.state==='installed' && navigator.serviceWorker.controller) showUpdate();});}); }).catch(()=>{});
function showUpdate(){updateReady=true;updateConnection();}
function showScreen(moveFocus=false) { const saved = location.hash === '#bookmarks', browsing = location.hash === '#browse', about = location.hash === '#help', home = !saved && !browsing && !about; document.body.classList.toggle('home-screen', home); $('#home').hidden = !home; $('#browse').hidden = !browsing; $('#help').hidden = !about; $('#bookmarks').hidden = !saved; document.querySelector('nav a[href="#home"]').setAttribute('aria-current', home ? 'page' : 'false'); document.querySelector('nav a[href="#bookmarks"]').setAttribute('aria-current', saved ? 'page' : 'false'); document.querySelector('nav a[href="#browse"]').setAttribute('aria-current', browsing ? 'page' : 'false'); document.querySelector('nav a[href="#help"]').setAttribute('aria-current', about ? 'page' : 'false'); window.scrollTo(0, 0); if(moveFocus) $(saved ? '#saved-title' : browsing ? '#results-title' : about ? '#help-title' : '#hero-title').focus({preventScroll:true}); }
window.addEventListener('hashchange', () => showScreen(true));
showScreen();
$('#openSources').addEventListener('click', () => $('#sourcesDialog').showModal());
$('#closeSources').addEventListener('click', () => $('#sourcesDialog').close());
$('#sourcesDialog').addEventListener('click', event => { if (event.target === $('#sourcesDialog')) $('#sourcesDialog').close(); });
